public long substrings(String s) {
    final long MOD = 1_000_000_007L;
    int n = s.length();
    long total = 0;
    for (int l = 0; l < n; l++) {
        long value = 0;
        for (int r = l; r < n; r++) {
            value = (value * 10 + (s.charAt(r) - '0')) % MOD;
            total = (total + value) % MOD;
        }
    }
    return total;
}

