public long substrings(String s) {
    final long MOD = 1_000_000_007L;
    long dp = 0, total = 0;
    for (int i = 0; i < s.length(); i++) {
        int d = s.charAt(i) - '0';
        dp = (dp * 10 + (long) (i + 1) * d) % MOD;
        total = (total + dp) % MOD;
    }
    return total;
}
